```python
import http.server
import json
import threading

class MessagesHandler(http.server.BaseHTTPRequestHandler):
    messages = []
    next_id = 0

    def log_message(self, format, *args):
        pass

    def do_POST(self):
        if self.path == '/api/messages':
            length = int(self.headers.get('Content-Length', 0))
            data = self.rfile.read(length)
            try:
                payload = json.loads(data.decode('utf-8'))
            except:
                self.send_response(400)
                self.end_headers()
                return
            user = payload.get('user', '')
            text = payload.get('text', '')
            global next_id
            next_id += 1
            msg = {'id': next_id, 'user': user, 'text': text}
            self.messages.append(msg)
            self.send_response(201)
            self.end_headers()
            self.wfile.write(json.dumps({}).encode())
        else:
            self.send_response(404)
            self.end_headers()

    def do_GET(self):
        if self.path.startswith('/api/messages'):
            # parse query params
            query = self.path
            # extract since
            try:
                since = int(self.parse_querystring(query).get('since', 0))
            except ValueError:
                since = 0
            filtered = [m for m in self.messages if m['id'] > since]
            self.send_response(200)
            body = json.dumps({'messages': filtered}).encode()
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404)
            self.end_headers()

    def parse_querystring(self, path):
        # simple parse
        if path.startswith('?'):
            query = path[2:]
        else:
            query = path
        params = {}
        if '?' in query:
            query, _, q = query.partition('&')
        while q:
            key, value = q.split('=', 1)
            params[key] = value
            q = q.split('&', 1)[1] if '&' in q else ''
        return params
```

